toolArgs.file_text:
@* Pagination with Previous, numbered pages, and Next buttons *@

@if (TotalPages > 1)
{
    <nav aria-label="Product catalog pagination" class="mt-4">
        <ul class="pagination justify-content-center flex-wrap">
            <li class="page-item @(CurrentPage <= 1 ? "disabled" : "")">
                <button class="page-link" @onclick="@(() => GoToPage(CurrentPage - 1))"
                        disabled="@(CurrentPage <= 1)">
                    Previous
                </button>
            </li>

            @foreach (var page in GetPageNumbers())
            {
                <li class="page-item @(page == CurrentPage ? "active" : "")">
                    <button class="page-link" @onclick="@(() => GoToPage(page))">@page</button>
                </li>
            }

            <li class="page-item @(CurrentPage >= TotalPages ? "disabled" : "")">
                <button class="page-link" @onclick="@(() => GoToPage(CurrentPage + 1))"
                        disabled="@(CurrentPage >= TotalPages)">
                    Next
                </button>
            </li>
        </ul>
    </nav>
}

@code {
    [Parameter] public int CurrentPage { get; set; } = 1;
    [Parameter] public int TotalPages { get; set; }
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
            await OnPageChanged.InvokeAsync(page);
    }

    /// <summary>
    /// Returns page numbers to display, with ellipsis-style windowing for large page counts.
    /// </summary>
    private IEnumerable<int> GetPageNumbers()
    {
        if (TotalPages <= 7)
            return Enumerable.Range(1, TotalPages);

        var pages = new SortedSet<int> { 1, TotalPages };
        for (int i = Math.Max(2, CurrentPage - 1); i <= Math.Min(TotalPages - 1, CurrentPage + 1); i++)
            pages.Add(i);

        return pages;
    }
}

arguments.file_text:
@page "/catalog"
@rendermode InteractiveServer
@using sv_1b2c4df73b564850940b614d47067fd1.Components.Catalog
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

@if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-link p-0 ms-2" @onclick="RetryLoad">Retry</button>
    </div>
}
else
{
    <div class="row">
        @* Left sidebar — filters *@
        <div class="col-lg-3 mb-3">
            <CatalogSidebar Categories="categories" OnFiltersApplied="HandleFiltersApplied" />
        </div>

        @* Main content area *@
        <div class="col-lg-9">
            <CatalogToolbar SortBy="@sortBy"
                            TotalCount="totalCount"
                            Page="currentPage"
                            PageSize="pageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (isLoading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading products…</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else
            {
                <ProductGrid Products="products"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="currentPage"
                                   TotalPages="totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        </div>
    </div>
}

@code {
    private List<Product> products = [];
    private List<string> categories = [];
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private int totalCount;
    private int totalPages;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            // Load categories and first page of products in parallel
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            categories = await categoriesTask;
            var result = await productsTask;

            products = result.Items;
            totalCount = result.TotalCount;
            totalPages = totalCount > 0 ? (int)Math.Ceiling((double)totalCount / pageSize) : 1;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products. {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;

            var result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
            products = result.Items;
            totalCount = result.TotalCount;
            totalPages = totalCount > 0 ? (int)Math.Ceiling((double)totalCount / pageSize) : 1;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products. {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        await OnAddToCart.InvokeAsync(product);
    }

    private async Task RetryLoad() => await LoadDataAsync();

    /// <summary>
    /// Notifies the parent when a product card is clicked for navigation to detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    /// <summary>
    /// Notifies the parent when Add to Cart is clicked.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

